head.script:
scwin.onpageload = function() {
	dlt_step1.setJSON([
		{ "cd": "10", "nm": "아시아", "useYn": "Y", "upCd": "" },
		{ "cd": "20", "nm": "아메리카", "useYn": "Y", "upCd": "" },
		{ "cd": "30", "nm": "유럽", "useYn": "Y", "upCd": "" },
		{ "cd": "40", "nm": "아프리카", "useYn": "Y", "upCd": "" },
		{ "cd": "50", "nm": "오세아니아", "useYn": "N", "upCd": "" }
	]);
	dlt_step2.setJSON([
		{ "cd": "11", "nm": "대한민국", "useYn": "Y", "upCd": "10" },
		{ "cd": "12", "nm": "중국", "useYn": "Y", "upCd": "10" },
		{ "cd": "13", "nm": "일본", "useYn": "N", "upCd": "10" },
		{ "cd": "21", "nm": "미국", "useYn": "Y", "upCd": "20" },
		{ "cd": "22", "nm": "캐나다", "useYn": "Y", "upCd": "20" },
		{ "cd": "23", "nm": "브라질", "useYn": "N", "upCd": "20" },
		{ "cd": "31", "nm": "영국", "useYn": "Y", "upCd": "30" },
		{ "cd": "32", "nm": "프랑스", "useYn": "Y", "upCd": "30" },
		{ "cd": "33", "nm": "독일", "useYn": "N", "upCd": "30" },
		{ "cd": "41", "nm": "이집트", "useYn": "Y", "upCd": "40" },
		{ "cd": "42", "nm": "가나", "useYn": "Y", "upCd": "40" },
		{ "cd": "43", "nm": "알제리", "useYn": "N", "upCd": "40" },
		{ "cd": "51", "nm": "호주", "useYn": "Y", "upCd": "50" },
		{ "cd": "52", "nm": "뉴질랜드", "useYn": "Y", "upCd": "50" }
	]);
	grd_sample.setColumnVisibleColumn("step1", "useYn", "N");
	// linkedDataList로 ItemSet한 컬럼에 setColumnVisibleColumn 적용시 초기값 셋팅하면 선택되어 있지 않는 문제
	grd_sample.setColumnVisibleColumn("step2", "useYn", "N");
};
scwin.dlt_sample_oncelldatachange = function(info) {
	if (info.colID == "step1") {
		// step1 변경시 step2 초기화
		dlt_sample.setCellData(info.rowIndex, "step2", "");
	}
};
scwin.btn_set_onclick = function(e) {
	// 그리드 다단콤보의 초기값 셋팅
	dlt_sample.setJSON([{
		step1: "20",
		step2: "23"
	}, {
		step1: "30",
		step2: "33"
	}, {
		step1: "50",
		step2: "52"
	}]);
};
